class Solution {
    private int count = 0;
    private char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};

    public int strobogrammaticInRange(String low, String high) {
        count = 0;
        for (int len = low.length(); len <= high.length(); len++) {
            if (len % 2 == 0) {
                dfs(0, len, "", low, high);
            } else {
                dfs(1, len, "0", low, high);
                dfs(1, len, "1", low, high);
                dfs(1, len, "8", low, high);
            }
        }
        return count;
    }

    private void dfs(int curLen, int targetLen, String path, String low, String high) {
        if (curLen == targetLen) {
            if ((low.length() < targetLen || path.compareTo(low) >= 0) && (targetLen < high.length() || path.compareTo(high) <= 0)) {
                count++;
            }
            return;
        }
        for (char[] p : pairs) {
            if (curLen + 2 == targetLen && p[0] == '0') continue;
            dfs(curLen + 2, targetLen, p[0] + path + p[1], low, high);
        }
    }
}

/**
 * @param {string} low
 * @param {string} high
 * @return {number}
 */
var strobogrammaticInRange = function(low, high) {
    const pairs = [['0', '0'], ['1', '1'], ['6', '9'], ['8', '8'], ['9', '6']];
    let count = 0;
    function dfs(curLen, targetLen, path) {
        if (curLen === targetLen) {
            if ((low.length < targetLen || path >= low) && (targetLen < high.length || path <= high)) {
                count++;
            }
            return;
        }
        for (const [l, r] of pairs) {
            if (curLen + 2 === targetLen && l === '0') continue;
            dfs(curLen + 2, targetLen, l + path + r);
        }
    }
    for (let len = low.length; len <= high.length; len++) {
        if (len % 2 === 0) {
            dfs(0, len, '');
        } else {
            dfs(1, len, '0');
            dfs(1, len, '1');
            dfs(1, len, '8');
        }
    }
    return count;
};
